INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000047',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk to a doctor in Hindi","Describe symptoms using mujhe X ho raha hai","Understand basic medical advice"],"explanation":{"intro":"At the doctor vocabulary covers describing symptoms, asking for medicine, and understanding a doctor''s instructions in Hindi.","culturalNote":"Healthcare in India: doctor (daaktar = डॉक्टर). Hospital (aspatal = अस्पताल). Clinic (clinic/dispensary). OPD (Out Patient Department). Prescription (prescription/parchee = पर्ची). Medicine (davaai = दवाई). Chemist/pharmacy (medical store = दवाई की दुकान). AIIMS (All India Institute of Medical Sciences) — India''s top public hospital. Apollo, Fortis — major private hospital chains. Doctor-patient relationship: very hierarchical in India — patients often do not question doctors. Key symptoms: bukhaar (बुखार = fever), khansi (खाँसी = cough), zukaam (ज़ुकाम = cold/runny nose), dard (दर्द = pain), ulti (उल्टी = vomiting), chhaalon (छाले = ulcers/blisters). Ayurveda (आयुर्वेद) — traditional Indian medicine — still widely used. Homeopathy also popular. Self-medication is very common — antibiotics available OTC (controversial). ABHA (Ayushman Bharat Health Account) — digital health ID. Janaushadhi scheme — generic medicines at low cost."},"examples":[{"hindi":"डॉक्टर, मुझे बुखार और सिरदर्द हो रहा है।","transliteration":"Doctor, mujhe bukhaar aur sirdard ho raha hai.","english":"Doctor, I have a fever and a headache."},{"hindi":"मुझे यह दवाई कब लेनी है?","transliteration":"Mujhe yah davaai kab leni hai?","english":"When do I need to take this medicine?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe symptoms to a doctor and understand basic medical advice in Hindi."}}',
'{"items":[{"word":"बुखार","translation":"fever","transliteration":"bukhaar","pronunciation":"bu-KHAAR","example":"बुखार होना।"},{"word":"दर्द","translation":"pain","transliteration":"dard","pronunciation":"dard","example":"सिरदर्द।"},{"word":"खाँसी","translation":"cough","transliteration":"khaansi","pronunciation":"KHAAN-si","example":"खाँसी होना।"},{"word":"दवाई","translation":"medicine","transliteration":"davaai","pronunciation":"da-VAA-ee","example":"दवाई लेना।"},{"word":"ज़ुकाम","translation":"cold/runny nose","transliteration":"zukaam","pronunciation":"zu-KAAM","example":"ज़ुकाम होना।"},{"word":"आराम","translation":"rest","transliteration":"aaraam","pronunciation":"aa-RAAM","example":"आराम करना।"}]}',
'{"title":"मुझे X हो रहा है — I am having/experiencing X (dative subject + ho raha hai)","pattern":"मुझे X हो रहा है = I am having/experiencing X. Dative subject: मुझे (to me). X = symptom/experience. हो रहा है = is happening (continuous of होना). Agreement: हो रहा है (masculine X) / हो रही है (feminine X). मुझे बुखार हो रहा है = I am having a fever (बुखार = masculine). मुझे खाँसी हो रही है = I am having a cough (खाँसी = feminine).","explanation":"Experiential construction: dative subject + X + ho raha/rahi hai. X is the experience/sensation. Used for: illness (bimari ho rahi hai = illness is happening to me), physical sensations, ongoing states. Different from: मुझे दर्द है (I have pain — stative). मुझे दर्द हो रहा है = I am experiencing/getting pain (ongoing). Also: भूख लगना (to feel hungry), प्यास लगना (to feel thirsty — lagana for felt sensations vs. hona for states).","examples":[{"sentence":"उसे उल्टी हो रही है।","transliteration":"Use ulti ho rahi hai.","translation":"She/he is vomiting/feeling nauseous."},{"sentence":"मुझे चक्कर आ रहे हैं।","transliteration":"Mujhe chakkar aa rahe hain.","translation":"I am feeling dizzy (dizziness is coming to me)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बुखार means?","options":["fever","cough","cold","pain"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Doctor, I have a fever and a headache.","options":["डॉक्टर, मुझे बुखार और सिरदर्द हो रहा है।","डॉक्टर, मुझे बुखार और खाँसी हो रही है।","डॉक्टर, मुझे ज़ुकाम और सिरदर्द हो रहा है।","डॉक्टर, मुझे बुखार और उल्टी हो रही है।"],"correctAnswer":"डॉक्टर, मुझे बुखार और सिरदर्द हो रहा है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"उसे उल्टी हो ___ है।","options":["रही","रहा","रहे","होती"],"correctAnswer":"रही"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When do I need to take this medicine?","wordBankItems":["मुझे","यह","दवाई","कब","लेनी","है","?"],"correctAnswer":"मुझे यह दवाई कब लेनी है ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"दवाई means?","options":["medicine","doctor","hospital","pain"],"correctAnswer":"medicine"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000048',1,'APPROVED','PUBLISHED',
'{"objectives":["Express emotions and feelings in Hindi","Use mujhe X lag raha hai for subjective states","Name emotions vocabulary"],"explanation":{"intro":"Emotions and feelings vocabulary covers how to express happiness, sadness, fear, anger, and other emotional states in Hindi.","culturalNote":"Emotions in Hindi: khushi (ख़ुशी = happiness), dukh (दुख = sadness/sorrow), gussa (ग़ुस्सा = anger), darr (डर = fear), pyaar (प्यार = love), nafrat (नफ़रत = hatred), utsaah (उत्साह = excitement/enthusiasm), udaasi (उदासी = melancholy), sharm (शर्म = shame/shyness). Key: Hindi/Urdu literary tradition — shayari (poetry) — is extraordinarily rich in emotional vocabulary. Gham (ग़म) = grief (Urdu). Khushi (ख़ुशी) = joy/happiness (Persian). The concept of ''izzat'' (इज़्ज़त = honor/respect) is central to Indian emotional vocabulary — loss of izzat is a profound emotional event. Pyaar vs. mohabbat vs. ishq — three Hindustani words for love with nuanced differences: pyaar (affection/love — colloquial), mohabbat (deep love — Urdu/poetic), ishq (passionate love — Urdu/mystical). Ek-taraf pyaar = one-sided love (unrequited). Dil (दिल = heart — used metaphorically like ''heart'' in English)."},"examples":[{"hindi":"मुझे बहुत ख़ुशी हो रही है।","transliteration":"Mujhe bahut khushi ho rahi hai.","english":"I am feeling very happy."},{"hindi":"उसे घर की याद आ रही है।","transliteration":"Use ghar ki yaad aa rahi hai.","english":"She/he is missing home (homesickness is coming to her/him)."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express emotions and feelings in Hindi."}}',
'{"items":[{"word":"ख़ुशी","translation":"happiness/joy","transliteration":"khushi","pronunciation":"khu-SHEE","example":"ख़ुशी होना।"},{"word":"दुख","translation":"sadness/sorrow","transliteration":"dukh","pronunciation":"dukh","example":"दुख में होना।"},{"word":"ग़ुस्सा","translation":"anger","transliteration":"gussa","pronunciation":"GUS-sa","example":"ग़ुस्सा आना।"},{"word":"डर","translation":"fear","transliteration":"dar","pronunciation":"dar","example":"डर लगना।"},{"word":"प्यार","translation":"love","transliteration":"pyaar","pronunciation":"pyaar","example":"प्यार करना।"},{"word":"याद","translation":"memory/remembrance","transliteration":"yaad","pronunciation":"yaad","example":"याद आना।"}]}',
'{"title":"मुझे X याद आना — to miss/remember X (yaad aana — idiomatic)","pattern":"मुझे X की याद आती है = I miss X / X''s memory comes to me. याद आना (yaad aana) = to come to mind, to miss. Dative subject: मुझे. याद is feminine → आती है (feminine agreement). X की याद = memory of X. Alternatively: X याद आता/आती है (X comes to mind — agreement with X gender).","explanation":"Idiomatic expressions with आना (aana = to come): several Hindi emotions use ''coming to'' the experiencer (dative subject). मुझे X याद आना = I remember/miss X. मुझे ग़ुस्सा आना = I get angry (anger comes to me). मुझे डर लगना = I feel scared (fear attaches to me). मुझे नींद आना = I feel sleepy (sleep comes to me). मुझे भूख लगना = I feel hungry. मुझे प्यास लगना = I feel thirsty. All these use dative subject (मुझे/उसे/हमें) — the emotion/sensation ''comes to'' or ''attaches to'' the person.","examples":[{"sentence":"मुझे अपने दोस्तों की याद आ रही है।","transliteration":"Mujhe apne doston ki yaad aa rahi hai.","translation":"I am missing my friends."},{"sentence":"उसे ग़ुस्सा आ गया।","transliteration":"Use gussa aa gaya.","translation":"She/he got angry (anger came to her/him)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ग़ुस्सा means?","options":["anger","fear","sadness","happiness"],"correctAnswer":"anger"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am feeling very happy.","options":["मुझे बहुत ख़ुशी हो रही है।","मुझे बहुत दुख हो रहा है।","मैं बहुत ख़ुश हूँ।","मुझे थोड़ी ख़ुशी हो रही है।"],"correctAnswer":"मुझे बहुत ख़ुशी हो रही है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे अपने दोस्तों की याद आ ___ है।","options":["रही","रहा","रहे","जाती"],"correctAnswer":"रही"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She/he is missing home.","wordBankItems":["उसे","घर","की","याद","आ","रही","है","।"],"correctAnswer":"उसे घर की याद आ रही है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"याद means?","options":["memory/remembrance","love","fear","sadness"],"correctAnswer":"memory/remembrance"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000049',1,'APPROVED','PUBLISHED',
'{"objectives":["Shop for clothes in Hindi","Use X ka size kya hai for size questions","Describe clothing preferences and colours"],"explanation":{"intro":"Shopping for clothes vocabulary covers fabric, size, colour, fit, and how to interact with a shopkeeper when buying clothes in Hindi.","culturalNote":"Clothes shopping in India: kapde ki dukaan (कपड़े की दुकान = clothes shop), fabric market (kapda bazaar = कपड़ा बाज़ार), mall (mall). Key clothing items: kurta (कुर्ता = long tunic — Indian men''s wear), salwar kameez (सलवार कमीज़ = tunic + trousers — women), saree (साड़ी = 6-yard draped garment — women), dhoti (धोती = traditional men''s wrap), lehenga (लहँगा = skirt + blouse — wedding wear), jeans + kurta (very popular urban mix). Size: XS/S/M/L/XL/XXL. Fabric (kapda = कपड़ा): cotton (suti = सूती), silk (resham = रेशम), synthetic (synthetic). Colour names: laal (red), peela (yellow), haraa (green), neela (blue), safed (white), kaala (black), narangi (orange), baingani (purple). Bargaining in local markets. MRP (Maximum Retail Price — printed on all packaged goods — illegal to sell above MRP — important consumer right in India)."},"examples":[{"hindi":"मुझे इस कुर्ते का मीडियम साइज़ चाहिए।","transliteration":"Mujhe is kurte ka medium size chahiye.","english":"I need a medium size of this kurta."},{"hindi":"क्या यह नीले रंग में भी आता है?","transliteration":"Kya yah neele rang mein bhi aata hai?","english":"Does this come in blue colour too?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can shop for clothes and describe clothing in Hindi."}}',
'{"items":[{"word":"कपड़ा","translation":"cloth/fabric","transliteration":"kapda","pronunciation":"KAP-da","example":"सूती कपड़ा।"},{"word":"साइज़","translation":"size","transliteration":"saiz","pronunciation":"SAA-iz","example":"साइज़ पूछना।"},{"word":"रंग","translation":"colour","transliteration":"rang","pronunciation":"rang","example":"नीला रंग।"},{"word":"पहनना","translation":"to wear","transliteration":"pahanna","pronunciation":"pa-HAN-na","example":"कुर्ता पहनना।"},{"word":"फ़िट होना","translation":"to fit","transliteration":"fit hona","pronunciation":"fit HO-na","example":"ठीक फ़िट होना।"},{"word":"सूती","translation":"cotton","transliteration":"sooti","pronunciation":"SOO-tee","example":"सूती कुर्ता।"}]}',
'{"title":"क्या X में भी Y आता है — Does X also come in Y? (availability in colour/size)","pattern":"क्या यह X में भी आता है? = Does this also come in X? आना (aana) for product availability: यह नीले रंग में आता है = This comes in blue colour. भी = also/too. X में = in X (in the colour/size X). Agreement: आता है (masculine item), आती है (feminine item).","explanation":"Product availability: X में आना = to come/be available in X (colour, size, flavour). यह आता है / आती है = it comes (agreement with product). क्या यह लाल रंग में आता है? = Does this come in red? Key: भी (bhi) = also/too — adds ''also'' to the question. Other forms: यह किन रंगों में आता है? = What colours does this come in? Pattern is widely used in retail: phone/TV/car/clothing colour/variant options.","examples":[{"sentence":"क्या यह जूता काले रंग में आता है?","transliteration":"Kya yah joota kaale rang mein aata hai?","translation":"Does this shoe come in black?"},{"sentence":"यह साड़ी हरे और लाल रंग में आती है।","transliteration":"Yah saari hare aur laal rang mein aati hai.","translation":"This saree comes in green and red."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"सूती means?","options":["cotton","silk","synthetic","wool"],"correctAnswer":"cotton"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Does this come in blue colour too?","options":["क्या यह नीले रंग में भी आता है?","क्या यह लाल रंग में भी आता है?","क्या यह नीले रंग में भी आती है?","क्या यह नीले साइज़ में भी आता है?"],"correctAnswer":"क्या यह नीले रंग में भी आता है?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह साड़ी हरे और लाल रंग में ___ है।","options":["आती","आता","आते","होती"],"correctAnswer":"आती"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I need a medium size of this kurta.","wordBankItems":["मुझे","इस","कुर्ते","का","मीडियम","साइज़","चाहिए","।"],"correctAnswer":"मुझे इस कुर्ते का मीडियम साइज़ चाहिए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"पहनना means?","options":["to wear","to buy","to try","to fit"],"correctAnswer":"to wear"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk to hotel staff in Hindi","Use X uplabdh hai for availability","Check in and out and describe room requirements"],"explanation":{"intro":"Hotel vocabulary covers checking in, describing room requirements, asking about facilities, and checking out in Hindi.","culturalNote":"Hotels in India: hotel (hotel) — remember ''hotel'' often means restaurant in many parts of India! Specifically: lodge (lodge), dharamshala (धर्मशाला = rest house — religious/charitable accommodation), homestay, resort (resort), heritage hotel (heritage hotel — many palaces converted). Star rating: 1-5 star (IHCL — Indian Hotels Company, Taj Hotels — among world''s best). Budget: OYO Rooms — India''s biggest hotel chain (aggregator model — thousands of budget properties). Checking in: ID proof (pehchaan patra = पहचान पत्र) mandatory — Aadhaar, passport, voter ID. Key requests: AC room (AC kamra = एसी कमरा), non-AC, single/double (single/double), attached bathroom (attached bathroom). Room service (room service). Checkout time: 11am-12pm standard. Key: Indian weddings fill entire hotels for days — wedding season (Oct-Feb) means bookings far in advance."},"examples":[{"hindi":"क्या कोई कमरा उपलब्ध है?","transliteration":"Kya koi kamra uplabdh hai?","english":"Is any room available?"},{"hindi":"मुझे दो रात के लिए एक डबल कमरा चाहिए।","transliteration":"Mujhe do raat ke liye ek double kamra chahiye.","english":"I need a double room for two nights."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can check into a hotel and describe my room requirements in Hindi."}}',
'{"items":[{"word":"कमरा","translation":"room","transliteration":"kamra","pronunciation":"KAM-ra","example":"एक कमरा।"},{"word":"उपलब्ध","translation":"available","transliteration":"uplabdh","pronunciation":"up-LAB-dh","example":"कमरा उपलब्ध।"},{"word":"चेक इन","translation":"check in","transliteration":"check in","pronunciation":"check in","example":"चेक इन करना।"},{"word":"चेक आउट","translation":"check out","transliteration":"check out","pronunciation":"check out","example":"चेक आउट करना।"},{"word":"सुविधाएँ","translation":"facilities/amenities","transliteration":"suvidhaen","pronunciation":"su-vi-DHAA-en","example":"सुविधाएँ देखना।"},{"word":"रात","translation":"night","transliteration":"raat","pronunciation":"raat","example":"दो रात।"}]}',
'{"title":"X के लिए Y रात — for Y nights (duration with ke liye)","pattern":"X के लिए Y रात = X for Y nights. के लिए = for (duration/purpose). दो रात के लिए = for two nights. तीन दिन के लिए = for three days. एक हफ़्ते के लिए = for one week. Used for hotel bookings, rentals, travel plans.","explanation":"Duration with के लिए: time-span + के लिए = for (a duration). रात (night — feminine), दिन (day — masculine), हफ़्ता (week — masculine), महीना (month — masculine). Numbers: दो रात (two nights), तीन दिन (three days), एक हफ़्ता (one week). Question: कितने दिन / कितनी रात के लिए? (for how many days/nights?). Compare: X के लिए purpose (यात्रा के लिए = for travel) vs. X के लिए duration (तीन दिन के लिए = for three days) — same construction, context distinguishes.","examples":[{"sentence":"हम यहाँ एक हफ़्ते के लिए आए हैं।","transliteration":"Hum yahaan ek hafte ke liye aaye hain.","translation":"We have come here for one week."},{"sentence":"कमरा कितने दिन के लिए चाहिए?","transliteration":"Kamra kitne din ke liye chahiye?","translation":"For how many days is the room needed?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"उपलब्ध means?","options":["available","vacant","clean","ready"],"correctAnswer":"available"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need a double room for two nights.","options":["मुझे दो रात के लिए एक डबल कमरा चाहिए।","मुझे तीन रात के लिए एक डबल कमरा चाहिए।","मुझे दो रात के लिए एक सिंगल कमरा चाहिए।","मुझे एक रात के लिए एक डबल कमरा चाहिए।"],"correctAnswer":"मुझे दो रात के लिए एक डबल कमरा चाहिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"हम यहाँ एक हफ़्ते के ___ आए हैं।","options":["लिए","लिया","साथ","से"],"correctAnswer":"लिए"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Is any room available?","wordBankItems":["क्या","कोई","कमरा","उपलब्ध","है","?"],"correctAnswer":"क्या कोई कमरा उपलब्ध है ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सुविधाएँ means?","options":["facilities/amenities","services","rooms","staff"],"correctAnswer":"facilities/amenities"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004b',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for and give directions in Hindi","Use X ke baad Y mudhna for turn-by-turn directions","Understand cardinal directions"],"explanation":{"intro":"Directions and navigation vocabulary covers how to ask for directions, describe a route, and use cardinal directions in Hindi.","culturalNote":"Asking for directions in India: rasta poochhna (रास्ता पूछना = to ask the way — very common). Key phrases: seedha jaiye (सीधा जाइए = go straight), baayen/daayein mudiye (बाएँ/दाएँ मुड़िए = turn left/right), X ke paas (near X), X ke saamne (opposite X), X ke peechhe (behind X). Landmarks: peepal ka ped (पीपल का पेड़ = peepal tree — common landmark), temple (mandir), bank, dhaba. Key: in India, directions are rarely given in distance — ''2km straight'' is less common than ''after the big temple, turn left, then you''ll see a chai shop.'' Landmarks are everything. GPS/Google Maps: widely used in cities but older generations and small towns still give landmark-based directions. Auto-drivers: asking them for directions often works well."},"examples":[{"hindi":"सीधे जाइए, फिर बाएँ मुड़िए।","transliteration":"Seedhe jaiye, phir baayen mudiye.","english":"Go straight, then turn left."},{"hindi":"बैंक मंदिर के सामने है।","transliteration":"Bank mandir ke saamne hai.","english":"The bank is opposite the temple."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for and give basic directions in Hindi."}}',
'{"items":[{"word":"सीधा","translation":"straight","transliteration":"seedha","pronunciation":"SEE-dha","example":"सीधे जाना।"},{"word":"बाएँ","translation":"left","transliteration":"baayen","pronunciation":"BAA-yen","example":"बाएँ मुड़ना।"},{"word":"दाएँ","translation":"right","transliteration":"daayen","pronunciation":"DAA-yen","example":"दाएँ मुड़ना।"},{"word":"मुड़ना","translation":"to turn","transliteration":"mudna","pronunciation":"MUD-na","example":"बाएँ मुड़ना।"},{"word":"सामने","translation":"in front/opposite","transliteration":"saamne","pronunciation":"SAAM-ne","example":"सामने की दुकान।"},{"word":"पास","translation":"near/close","transliteration":"paas","pronunciation":"paas","example":"पास में।"}]}',
'{"title":"X के सामने/पीछे/बगल में — opposite/behind/beside X (relative location postpositions)","pattern":"X के सामने = in front of / opposite X. X के पीछे = behind X. X के बगल में = beside/next to X. X के ऊपर = above X. X के नीचे = below X. All require oblique of X and के before the postposition. मंदिर के सामने = opposite the temple. बैंक के बगल में = next to the bank.","explanation":"Location postpositions with के: compound postpositions (two-word postpositions) follow X के + location word. All require X in oblique (consonant-final nouns: same as direct; vowel-final masculine -a nouns: -e, e.g. मंदिर stays, घर stays, दुकान stays, बाज़ार stays). Key postpositions: के सामने (in front/opposite), के पीछे (behind), के बगल में (beside), के अंदर (inside), के बाहर (outside), के ऊपर (above/on top), के नीचे (below), के पास (near). Essential for navigation and description.","examples":[{"sentence":"स्कूल बाज़ार के पीछे है।","transliteration":"Skool baazaar ke peeche hai.","translation":"The school is behind the market."},{"sentence":"मेरा घर मंदिर के बगल में है।","transliteration":"Mera ghar mandir ke bagal mein hai.","translation":"My house is next to the temple."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"सामने means?","options":["in front/opposite","behind","beside","above"],"correctAnswer":"in front/opposite"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Go straight, then turn left.","options":["सीधे जाइए, फिर बाएँ मुड़िए।","सीधे जाइए, फिर दाएँ मुड़िए।","बाएँ जाइए, फिर सीधे मुड़िए।","सीधे जाइए, फिर बाएँ जाइए।"],"correctAnswer":"सीधे जाइए, फिर बाएँ मुड़िए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"स्कूल बाज़ार के ___ है।","options":["पीछे","सामने","बगल","ऊपर"],"correctAnswer":"पीछे"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The bank is opposite the temple.","wordBankItems":["बैंक","मंदिर","के","सामने","है","।"],"correctAnswer":"बैंक मंदिर के सामने है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मुड़ना means?","options":["to turn","to go","to stop","to walk"],"correctAnswer":"to turn"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004c',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about sports and exercise in Hindi","Use X khelna for team sports and X karna for activities","Describe fitness routines"],"explanation":{"intro":"Sports and exercise vocabulary covers popular sports, fitness activities, and how to describe your exercise habits in Hindi.","culturalNote":"Sports in India: cricket (cricket — religion in India — the national obsession), kabaddi (कबड्डी — contact sport, now PKL Pro Kabaddi League), hockey (हॉकी = India''s official national sport — historically dominant in Olympics), badminton (badminton — PV Sindhu, Saina Nehwal — major global stars), wrestling (kushti = कुश्ती — traditional — now wrestling: Bajrang Punia, Vinesh Phogat, Sushil Kumar), football (soccer in South India — Kerala, Goa), tennis (Sania Mirza, Leander Paes). Yoga: India is the birthplace — International Yoga Day (June 21 — India proposed at UN). Gym culture expanding rapidly in cities. Jogging: early morning joggers in parks are a very common urban sight. Key TV: IPL cricket has the highest TV ratings in India. Fitness apps: Cult.fit very popular."},"examples":[{"hindi":"मैं हर सुबह योग करता हूँ।","transliteration":"Main har subah yog karta hoon.","english":"I do yoga every morning."},{"hindi":"भारत में क्रिकेट सबसे लोकप्रिय खेल है।","transliteration":"Bharat mein cricket sabse lokpriya khel hai.","english":"Cricket is the most popular sport in India."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about sports and exercise habits in Hindi."}}',
'{"items":[{"word":"खेल","translation":"sport/game","transliteration":"khel","pronunciation":"khel","example":"खेल खेलना।"},{"word":"जीतना","translation":"to win","transliteration":"jeetna","pronunciation":"JEET-na","example":"मैच जीतना।"},{"word":"हारना","translation":"to lose","transliteration":"haarna","pronunciation":"HAAR-na","example":"मैच हारना।"},{"word":"अभ्यास","translation":"practice/training","transliteration":"abhyas","pronunciation":"ab-HYAS","example":"अभ्यास करना।"},{"word":"लोकप्रिय","translation":"popular","transliteration":"lokpriya","pronunciation":"lok-PRI-ya","example":"लोकप्रिय खेल।"},{"word":"मैच","translation":"match/game","transliteration":"match","pronunciation":"match","example":"मैच खेलना।"}]}',
'{"title":"X में Y सबसे Z है — Y is the most Z in X (superlative with sabse)","pattern":"सबसे (sabse) = most (superlative marker). X में Y सबसे Z है = In X, Y is the most Z. सबसे + adjective = most + adjective. सबसे बड़ा = biggest. सबसे लोकप्रिय = most popular. सबसे अच्छा = best. सबसे महँगा = most expensive. No agreement change on सबसे itself — the adjective still agrees with Y.","explanation":"Superlative in Hindi: सबसे + adjective. सबसे (sabse) = literally ''from all'' (sab = all + se = from/among). सबसे बड़ा = biggest (among all). सबसे अच्छा = best. सबसे ज़्यादा = most (quantity). सबसे कम = least. Agreement: the adjective after सबसे still agrees with the noun. सबसे बड़ी टीम (biggest team — feminine). Comparative: X, Y से बड़ा है = X is bigger than Y (se = than). Pattern: Y, X से Z है = Y is more Z than X.","examples":[{"sentence":"हिमालय दुनिया का सबसे बड़ा पर्वत है।","transliteration":"Himalay duniya ka sabse bada parvat hai.","translation":"The Himalayas are the world''s biggest mountain."},{"sentence":"यह मेरी सबसे पसंदीदा टीम है।","transliteration":"Yah meri sabse pasandida team hai.","translation":"This is my most favourite team."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"लोकप्रिय means?","options":["popular","favourite","best","famous"],"correctAnswer":"popular"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Cricket is the most popular sport in India.","options":["भारत में क्रिकेट सबसे लोकप्रिय खेल है।","भारत में कबड्डी सबसे लोकप्रिय खेल है।","विश्व में क्रिकेट सबसे लोकप्रिय खेल है।","भारत में क्रिकेट एक लोकप्रिय खेल है।"],"correctAnswer":"भारत में क्रिकेट सबसे लोकप्रिय खेल है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह मेरी सबसे ___ टीम है।","options":["पसंदीदा","लोकप्रिय","अच्छी","बड़ी"],"correctAnswer":"पसंदीदा"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I do yoga every morning.","wordBankItems":["मैं","हर","सुबह","योग","करता","हूँ","।"],"correctAnswer":"मैं हर सुबह योग करता हूँ ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"जीतना means?","options":["to win","to lose","to play","to practise"],"correctAnswer":"to win"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about festivals and celebrations in Hindi","Use X manaana for celebrating","Name major Indian festivals"],"explanation":{"intro":"Festivals and celebrations vocabulary covers major Indian festivals, how to celebrate, and how to give and receive wishes in Hindi.","culturalNote":"Major Indian festivals: Diwali (दीवाली/दीपावली = festival of lights — October/November — most popular — Lakshmi puja, firecrackers, mithai). Holi (होली = festival of colours — March — spring — phoolon wali Holi, gulaal/rang). Eid-ul-Fitr and Eid-ul-Adha (Muslim — seviyan/biryani). Christmas (December 25 — national holiday). Durga Puja/Navratri (nine nights — Goddess Durga). Ganesh Chaturthi (Maharashtra — massive celebrations — Ganpati bappa morya!). Onam (Kerala — harvest festival). Lohri (Punjab — harvest). Baisakhi (Punjabi new year + harvest). Dussehra/Vijayadasami (Ram''s victory over Ravana — Ramlila). Janmashtami (Krishna''s birthday). Key: India has more national and state holidays than almost any country. Mubarak/Badhai: mubarak ho / badhai ho = congratulations (used for festivals and achievements)."},"examples":[{"hindi":"दीवाली में हम पटाखे जलाते हैं।","transliteration":"Diwali mein hum pataakhe jalaate hain.","english":"At Diwali we light firecrackers."},{"hindi":"होली की हार्दिक शुभकामनाएँ!","transliteration":"Holi ki haardik shubhkaamnaaen!","english":"Warm wishes for Holi!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about Indian festivals and give festival wishes in Hindi."}}',
'{"items":[{"word":"त्योहार","translation":"festival","transliteration":"tyohaar","pronunciation":"tyo-HAAR","example":"त्योहार मनाना।"},{"word":"मनाना","translation":"to celebrate","transliteration":"manaana","pronunciation":"ma-NAA-na","example":"दीवाली मनाना।"},{"word":"शुभकामनाएँ","translation":"good wishes","transliteration":"shubhkaamnaaen","pronunciation":"shubh-kaam-NAA-en","example":"शुभकामनाएँ देना।"},{"word":"पटाखे","translation":"firecrackers","transliteration":"pataakhe","pronunciation":"pa-TAAK-he","example":"पटाखे जलाना।"},{"word":"मिठाई","translation":"sweets","transliteration":"mithaai","pronunciation":"mi-THAAI","example":"मिठाई बाँटना।"},{"word":"खुशी","translation":"happiness/joy","transliteration":"khushi","pronunciation":"khu-SHEE","example":"खुशी मनाना।"}]}',
'{"title":"X की हार्दिक शुभकामनाएँ — Warm wishes for X (festival greeting formula)","pattern":"X की हार्दिक शुभकामनाएँ = Warm wishes for X. X = festival name. की = possessive (शुभकामनाएँ की X = wishes of X). हार्दिक = heartfelt/warm (from Sanskrit hriday = heart). शुभकामनाएँ = good wishes (plural of शुभकामना). Standard formula for all festivals. Alternative: X मुबारक हो (X be blessed — Urdu style) or X की बधाई हो (X congratulations).","explanation":"Festival wishes in Hindi: Standard formula: [Festival] की हार्दिक शुभकामनाएँ. Variations: दीपावली की शुभकामनाएँ (Diwali wishes), ईद मुबारक (Eid Mubarak), होली की बधाई (Holi congratulations). हार्दिक (haardik) = heartfelt/warm — from Sanskrit. शुभ = auspicious/good. कामना = wish/desire. Responding: आपको भी (to you also), धन्यवाद (thank you), शुभकामनाएँ (same wishes back). These formulas are essential for Indian social interactions — WhatsApp forwards millions of festival wishes every year.","examples":[{"sentence":"आपको और आपके परिवार को दीवाली की शुभकामनाएँ।","transliteration":"Aapko aur aapke parivaar ko Diwali ki shubhkaamnaaen.","translation":"Diwali wishes to you and your family."},{"sentence":"ईद मुबारक! — शुक्रिया, आपको भी।","transliteration":"Eid Mubarak! — Shukriya, aapko bhi.","translation":"Eid Mubarak! — Thank you, to you also."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"त्योहार means?","options":["festival","celebration","holiday","event"],"correctAnswer":"festival"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"At Diwali we light firecrackers.","options":["दीवाली में हम पटाखे जलाते हैं।","होली में हम पटाखे जलाते हैं।","दीवाली में वे पटाखे जलाते हैं।","दीवाली में हम दीये जलाते हैं।"],"correctAnswer":"दीवाली में हम पटाखे जलाते हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"होली की हार्दिक ___ !","options":["शुभकामनाएँ","बधाई","मुबारक","नमस्ते"],"correctAnswer":"शुभकामनाएँ"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Diwali wishes to you and your family.","wordBankItems":["आपको","और","आपके","परिवार","को","दीवाली","की","शुभकामनाएँ","।"],"correctAnswer":"आपको और आपके परिवार को दीवाली की शुभकामनाएँ ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मिठाई means?","options":["sweets","snacks","food","cake"],"correctAnswer":"sweets"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004e',1,'APPROVED','PUBLISHED',
'{"objectives":["Name animals and nature in Hindi","Use X ke jangalon mein for habitat","Talk about Indian wildlife"],"explanation":{"intro":"Animals and nature vocabulary covers domestic and wild animals, habitats, and Indian wildlife in Hindi.","culturalNote":"India''s incredible wildlife: India is one of the world''s mega-biodiverse countries. National animal: Tiger (Baaghh = बाघ — Bengal tiger — Project Tiger 1973 — now ~3000 tigers — conservation success). National bird: Peacock (Mor = मोर). National flower: Lotus (Kamal = कमल). Endangered: Indian elephant (haathi = हाथी — Asian elephant), Snow leopard (him tendua), One-horned rhino (gainda = गैंडा — Kaziranga, Assam — world''s largest population). Sacred: Cow (gaay = गाय — sacred in Hinduism — protected in most states). Nandi (Shiva''s bull). Monkey (bandar = बंदर — Hanuman — sacred — Macaques everywhere at temples). Snake (saanp = साँप — Naga deity — Nag Panchami festival). Key ecosystems: Western Ghats (biodiversity hotspot), Sundarban mangroves (Gangetic delta — tigers), Himalayan range, Thar Desert (camel = ooNt = ऊँट)."},"examples":[{"hindi":"भारत के जंगलों में बाघ और हाथी रहते हैं।","transliteration":"Bharat ke jangalon mein baagh aur haathi rehte hain.","english":"Tigers and elephants live in India''s forests."},{"hindi":"गाय भारत में एक पवित्र पशु है।","transliteration":"Gaay Bharat mein ek pavitra pashu hai.","english":"The cow is a sacred animal in India."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name animals and talk about Indian wildlife in Hindi."}}',
'{"items":[{"word":"बाघ","translation":"tiger","transliteration":"baagh","pronunciation":"baagh","example":"जंगल में बाघ।"},{"word":"हाथी","translation":"elephant","transliteration":"haathi","pronunciation":"HAATI","example":"हाथी का झुंड।"},{"word":"जंगल","translation":"forest/jungle","transliteration":"jangal","pronunciation":"JAN-gal","example":"घना जंगल।"},{"word":"पवित्र","translation":"sacred/holy","transliteration":"pavitra","pronunciation":"pa-VIT-ra","example":"पवित्र पशु।"},{"word":"पशु","translation":"animal","transliteration":"pashu","pronunciation":"PA-shu","example":"जंगली पशु।"},{"word":"पक्षी","translation":"bird","transliteration":"pakshi","pronunciation":"PAK-shi","example":"सुंदर पक्षी।"}]}',
'{"title":"X के जंगलों में Y रहते हैं — Y lives in the forests of X (habitat description)","pattern":"X के जंगलों में Y रहते हैं = Y lives in the forests of X. X के (oblique possessive) + जंगलों में (in forests — oblique plural of जंगल). Y रहते हैं = Y lives (habitual 3rd person plural — used for animals and people). Singular: Y रहता/रहती है. Plural habitat: forests, mountains, jungles → plural जंगलों में.","explanation":"Habitat description: place + में + animal + रहता/रहती/रहते है/हैं. Plural के: oblique plural of masculine -a nouns: जंगल (invariant plural — already ends in consonant) → जंगलों में (with में, oblique plural adds -ों). पहाड़ (mountain) → पहाड़ों में (in mountains). नदी (river, feminine) → नदियों में (in rivers). Key: habitual present (रहता है) expresses permanent states and general truths — animals always living in their habitat. Compare: X में रहना (to live in X) vs. X में रह रहे हैं (living in X right now — continuous).","examples":[{"sentence":"हिमालय में हिम तेंदुए रहते हैं।","transliteration":"Himalay mein him tenduve rehte hain.","translation":"Snow leopards live in the Himalayas."},{"sentence":"गंगा नदी में डॉल्फ़िन पाई जाती है।","transliteration":"Ganga nadi mein dolphin pai jaati hai.","translation":"Dolphins are found in the Ganges river."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बाघ means?","options":["tiger","elephant","lion","leopard"],"correctAnswer":"tiger"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tigers and elephants live in India''s forests.","options":["भारत के जंगलों में बाघ और हाथी रहते हैं।","भारत के जंगलों में शेर और हाथी रहते हैं।","भारत की नदियों में बाघ और हाथी रहते हैं।","जंगल में बाघ और हाथी रहते हैं।"],"correctAnswer":"भारत के जंगलों में बाघ और हाथी रहते हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"हिमालय में हिम तेंदुए ___ हैं।","options":["रहते","रहता","रहती","मिलते"],"correctAnswer":"रहते"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The cow is a sacred animal in India.","wordBankItems":["गाय","भारत","में","एक","पवित्र","पशु","है","।"],"correctAnswer":"गाय भारत में एक पवित्र पशु है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"पवित्र means?","options":["sacred/holy","beautiful","important","ancient"],"correctAnswer":"sacred/holy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000004f',1,'APPROVED','PUBLISHED',
'{"objectives":["Count in Hindi from 100 to 1 million","Use ek sau, do sau for hundreds","Understand lakh and crore system"],"explanation":{"intro":"Numbers 100 and beyond covers hundreds, thousands, lakhs, and crores — India''s unique counting system that differs from the Western system in Hindi.","culturalNote":"India''s number system: ek sau (100 = एक सौ), do sau (200), ek hazaar (1,000 = एक हज़ार), das hazaar (10,000), ek lakh (1,00,000 = एक लाख = 100,000 — key difference from Western system!), das lakh (10 lakh = 1 million), ek crore (1,00,00,000 = एक करोड़ = 10 million). The lakh-crore system: India uses lakh (lakh = 1,00,000) and crore (crore = 1,00,00,000 = 10 million) — not million and billion. So: 1 million = 10 lakh, 1 billion = 100 crore. Comma placement: India places commas differently — 1,00,000 (one lakh) not 100,000. Stock market: sensex, nifty. GDP: quoted in crore rupees. Population: 140 crore (=1.4 billion). Key: any Indian newspaper will use lakh and crore — essential to understand. Mobile number: 10 digits. PIN code: 6 digits."},"examples":[{"hindi":"इस शहर की जनसंख्या दस लाख है।","transliteration":"Is shahar ki jansankhya das lakh hai.","english":"The population of this city is one million (ten lakh)."},{"hindi":"एक करोड़ रुपये बहुत बड़ी रकम है।","transliteration":"Ek crore rupaye bahut badi rakam hai.","english":"One crore rupees is a very large amount."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can count from 100 to 1 crore in Hindi and understand the lakh-crore system."}}',
'{"items":[{"word":"सौ","translation":"hundred","transliteration":"sau","pronunciation":"sau","example":"एक सौ।"},{"word":"हज़ार","translation":"thousand","transliteration":"hazaar","pronunciation":"ha-ZAAR","example":"एक हज़ार।"},{"word":"लाख","translation":"one hundred thousand","transliteration":"laakh","pronunciation":"laakh","example":"दस लाख।"},{"word":"करोड़","translation":"ten million","transliteration":"crore","pronunciation":"ka-ROD","example":"एक करोड़।"},{"word":"जनसंख्या","translation":"population","transliteration":"jansankhya","pronunciation":"jan-SAN-khya","example":"देश की जनसंख्या।"},{"word":"रकम","translation":"amount/sum","transliteration":"rakam","pronunciation":"RA-kam","example":"बड़ी रकम।"}]}',
'{"title":"Lakh-crore number system — Indian counting beyond thousands","pattern":"100 = एक सौ. 200 = दो सौ. 1,000 = एक हज़ार. 10,000 = दस हज़ार. 1,00,000 = एक लाख. 10,00,000 = दस लाख (= 1 million). 1,00,00,000 = एक करोड़ (= 10 million). 100 करोड़ = 1 अरब (= 1 billion). The system groups by 2 above 1,000: so 1,00,000 (not 100,000 in Indian comma system).","explanation":"Indian number system: unlike Western system (thousand, million, billion), India uses: हज़ार (1,000), लाख (1,00,000 = 10 × 1,000), करोड़ (1,00,00,000 = 100 × 1,000 × 100). Arithmetic: 140 crore = 140,00,00,000 = 1,400,000,000 (1.4 billion). 50 lakh = 50,00,000 = 5,000,000 (5 million). Reading: 2,50,000 = do lakh pachaas hazaar (2 lakh 50 thousand). Writing numbers: say number in descending order of lakh → hazaar → remainder. 3,45,678 = teen lakh paentalis hazaar chhe sau athattar.","examples":[{"sentence":"भारत की जनसंख्या लगभग 140 करोड़ है।","transliteration":"Bharat ki jansankhya lagbhag 140 crore hai.","translation":"India''s population is approximately 140 crore (1.4 billion)."},{"sentence":"उसने पाँच लाख रुपये में घर ख़रीदा।","transliteration":"Usne paanch lakh rupaye mein ghar kharida.","translation":"She/he bought the house for five lakh rupees."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"लाख means?","options":["one hundred thousand","thousand","million","billion"],"correctAnswer":"one hundred thousand"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The population of this city is one million (ten lakh).","options":["इस शहर की जनसंख्या दस लाख है।","इस शहर की जनसंख्या एक लाख है।","इस देश की जनसंख्या दस लाख है।","इस शहर की जनसंख्या दस हज़ार है।"],"correctAnswer":"इस शहर की जनसंख्या दस लाख है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"भारत की जनसंख्या लगभग 140 ___ है।","options":["करोड़","लाख","हज़ार","सौ"],"correctAnswer":"करोड़"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: One crore rupees is a very large amount.","wordBankItems":["एक","करोड़","रुपये","बहुत","बड़ी","रकम","है","।"],"correctAnswer":"एक करोड़ रुपये बहुत बड़ी रकम है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"करोड़ means?","options":["ten million","hundred thousand","thousand","million"],"correctAnswer":"ten million"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000050',1,'APPROVED','PUBLISHED',
'{"objectives":["Make comparisons in Hindi","Use X se zyada and X se kam for more and less","Compare people, things, and places"],"explanation":{"intro":"Comparisons vocabulary covers how to say more, less, better, and worse using the comparative construction with se in Hindi.","culturalNote":"Making comparisons in Hindi: zyada (ज़्यादा = more — from Persian), kam (कम = less/fewer), behtar (बेहतर = better — from Persian beht), badtar (बदतर = worse), bada (बड़ा = bigger), chota (छोटा = smaller). Key: Hindi uses se (from/than) to mark the standard of comparison — X, Y se bada hai = X is bigger than Y (literally: ''X is big from Y''). This is very different from English ''than'' — se comes after the comparison standard. Social comparisons are very common in Indian conversation: school marks, salaries, marriage prospects — relatives frequently compare children''s achievements."},"examples":[{"hindi":"दिल्ली मुंबई से बड़ी है।","transliteration":"Delhi Mumbai se badi hai.","english":"Delhi is bigger than Mumbai."},{"hindi":"हिंदी अंग्रेज़ी से कठिन है।","transliteration":"Hindi Angrezi se kathin hai.","english":"Hindi is more difficult than English."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can make comparisons using more, less, bigger, and better in Hindi."}}',
'{"items":[{"word":"ज़्यादा","translation":"more/a lot","transliteration":"zyada","pronunciation":"ZYAA-da","example":"ज़्यादा खाना।"},{"word":"कम","translation":"less/fewer","transliteration":"kam","pronunciation":"kam","example":"कम पैसे।"},{"word":"बेहतर","translation":"better","transliteration":"behtar","pronunciation":"BEH-tar","example":"बेहतर विकल्प।"},{"word":"से","translation":"than (in comparisons)","transliteration":"se","pronunciation":"se","example":"X से बड़ा।"},{"word":"कठिन","translation":"difficult/hard","transliteration":"kathin","pronunciation":"KA-thin","example":"कठिन काम।"},{"word":"आसान","translation":"easy","transliteration":"aasaan","pronunciation":"aa-SAAN","example":"आसान रास्ता।"}]}',
'{"title":"X, Y से Z है — X is more Z than Y (comparative with se)","pattern":"X, Y से Z है = X is Z-er than Y / X is more Z than Y. से (se) = from/than (marks the comparison standard — the thing being compared against). Y से (than Y) comes after Y. Z = adjective. दिल्ली, मुंबई से बड़ी है = Delhi is bigger than Mumbai. Adding ज़्यादा: X, Y से ज़्यादा Z है = X is more Z than Y (explicit). X, Y से कम Z है = X is less Z than Y.","explanation":"Comparative construction: X, Y से [adjective] है. Y से = than Y (from Y — higher than). The comparison standard takes से. There is no separate comparative suffix like English -er — the base adjective is used. ज़्यादा (more) can be added explicitly: Y से ज़्यादा = more than Y. कम (less) also possible: Y से कम = less than Y. Superlative: सबसे = most (from all). Equality: X, Y जितना Z है = X is as Z as Y (jitna = as much as). Practice: मेरा भाई मुझसे लंबा है = My brother is taller than me.","examples":[{"sentence":"यह कमरा उससे सस्ता है।","transliteration":"Yah kamra usse sasta hai.","translation":"This room is cheaper than that one."},{"sentence":"मेरा भाई मुझसे लंबा है।","transliteration":"Mera bhai mujhse lamba hai.","translation":"My brother is taller than me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ज़्यादा means?","options":["more/a lot","less","enough","very"],"correctAnswer":"more/a lot"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Delhi is bigger than Mumbai.","options":["दिल्ली मुंबई से बड़ी है।","मुंबई दिल्ली से बड़ी है।","दिल्ली मुंबई से छोटी है।","दिल्ली मुंबई से बड़ा है।"],"correctAnswer":"दिल्ली मुंबई से बड़ी है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरा भाई मुझ___ लंबा है।","options":["से","को","में","पर"],"correctAnswer":"से"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Hindi is more difficult than English.","wordBankItems":["हिंदी","अंग्रेज़ी","से","कठिन","है","।"],"correctAnswer":"हिंदी अंग्रेज़ी से कठिन है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बेहतर means?","options":["better","best","good","excellent"],"correctAnswer":"better"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

